{% set flights = states.sensor | selectattr('attributes.flight_number','defined') | list %}
{% set ns = namespace(count=0) %}
{% for f in flights | sort(attribute='attributes.departure_date',reverse=true) %}
{% if f.attributes.get('finalized_at') or f.state | lower in ['landed','canceled','cancelled'] %}
{% set ns.count = ns.count + 1 %}
{% set m = f.attributes.get('metadata') or {} %}
{% set ac = f.attributes.get('aircraft') or {} %}
{% set t = f.attributes.get('operational_times') or {} %}
{% set scheduled_arr = f.attributes.get('scheduled_arrival_utc') or m.get('scheduled_arrival_utc') %}
{% set scheduled_dep = f.attributes.get('scheduled_departure_utc') or m.get('scheduled_departure_utc') %}
{% set actual_dep = f.attributes.get('actual_departure_utc') %}
{% set stored_arr = f.attributes.get('actual_arrival_utc') %}
{% set finalized = f.attributes.get('finalized_at') %}
{% set actual_arr = (t.get('gate_arrival_utc') or {}).get('utc') or (stored_arr if stored_arr and (not finalized or (as_timestamp(stored_arr) - as_timestamp(finalized)) | abs > 2) else none) %}
{% set arr_diff = ((as_timestamp(actual_arr) - as_timestamp(scheduled_arr)) / 60) | round(0) | int if actual_arr and scheduled_arr else none %}
{% set dep_diff = ((as_timestamp(actual_dep) - as_timestamp(scheduled_dep)) / 60) | round(0) | int if actual_dep and scheduled_dep else none %}
{% set duration = ((as_timestamp(actual_arr) - as_timestamp(actual_dep)) / 60) | round(0) | int if actual_arr and actual_dep else none %}
**{{ f.attributes.flight_number }}** · {{ m.get('departure_airport','—') }} → {{ m.get('arrival_airport','—') }}  
{{ f.attributes.departure_date }} · {{ f.state | title }}{% if ac.get('registration') %} · {{ ac.get('registration') }}{% endif %}{% if ac.get('jetphotos_url') %} · [Photos]({{ ac.get('jetphotos_url') }}){% endif %}  
**Distance:** {{ '{:,.0f}'.format(f.attributes.distance_miles) ~ ' mi (direct)' if f.attributes.get('distance_miles') is number else 'Unavailable' }} · **Trip duration:** {{ (duration // 60) ~ 'h ' ~ (duration % 60) ~ 'm' if duration is not none and duration >= 0 else 'Unavailable' }}  
**Arrival:** {% if arr_diff is none %}Variance unavailable{% elif arr_diff < 0 %}{{ -arr_diff }} min early{% elif arr_diff > 15 %}{{ arr_diff }} min delayed{% elif arr_diff > 0 %}{{ arr_diff }} min late (on time){% else %}On time{% endif %} · **Departure:** {% if dep_diff is none %}Variance unavailable{% elif dep_diff < 0 %}{{ -dep_diff }} min early{% elif dep_diff > 0 %}{{ dep_diff }} min late{% else %}On time{% endif %}
{% if t.get('gate_departure_utc') %}  
Left gate {{ as_local(as_datetime(t['gate_departure_utc']['utc'])).strftime('%I:%M %p') }}{% endif %}{% if t.get('gate_arrival_utc') %} · Arrived gate {{ as_local(as_datetime(t['gate_arrival_utc']['utc'])).strftime('%I:%M %p') }}{% endif %}

---
{% endif %}
{% endfor %}
{% if ns.count == 0 %}No completed flights yet.{% endif %}

